    private void offerUpdate(UpdateManager.Release release){if(!alive())return;new AlertDialog.Builder(this).setTitle("Доступна версия "+release.version).setMessage("Скачать обновление и открыть установщик Android?").setNegativeButton(tr("Позже"),null).setPositiveButton(tr("Обновить"),(dialog,which)->{setStatus(tr("Загружаю обновление…"));UpdateManager.download(this,release,message->{if(alive())new AlertDialog.Builder(this).setMessage(message).setPositiveButton(tr("Понятно"),null).show();});}).show();}
    private void applyPalette(){boolean dark=(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES;BG=dark?0xff10131b:0xfff5f6fa;WHITE=dark?0xff1a1f2b:0xffffffff;INK=dark?0xfff2f4fa:0xff171b27;MUTED=dark?0xffa3aec1:0xff697284;ACCENT=dark?0xff9ab0ff:0xff4265dc;LINE=dark?0xff303849:0xffe2e6ef;getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);}
