        nav=row();nav.setPadding(dp(8),dp(6),dp(8),dp(8));String[] names={tr("Библиотека"),tr("Авторы"),tr("Мои"),tr("Аккаунт")};int[] icons={R.drawable.nav_library,R.drawable.nav_users,R.drawable.nav_file,R.drawable.nav_user};for(int i=0;i<4;i++){final int index=i;Button b=button(names[i],()->{hideKeyboard();screen=index;render();if(index==2)loadOwn();});b.setTextSize(11);b.setPadding(0,dp(5),0,dp(5));b.setBackground(bg(i==screen?INK:BG,10));b.setTextColor(i==screen?WHITE:MUTED);android.graphics.drawable.Drawable icon=getDrawable(icons[i]).mutate();icon.setTint(i==screen?WHITE:MUTED);b.setCompoundDrawablesWithIntrinsicBounds(null,icon,null,null);b.setCompoundDrawablePadding(dp(2));b.setGravity(Gravity.CENTER);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(58),1);p.setMargins(dp(2),0,dp(2),0);nav.addView(b,p);}root.addView(nav);
